def dedupe(xs):
    out = []
    i = 0
    while i < len(xs):
        out.append(xs[i])
        # skip the next element if it repeats this one
        i += 2 if i + 1 < len(xs) and xs[i + 1] == xs[i] else 1
    return out

def reference(xs):
    out = []
    for x in xs:
        if not out or out[-1] != x:
            out.append(x)
    return out

def fails(xs):
    return dedupe(xs) != reference(xs)

data = [4, 7, 7, 2, 2, 2, 9]
print("original fails:", fails(data), "- buggy:", dedupe(data), "expected:", reference(data))
current = data[:]
while True:
    removed = False
    for i in range(len(current)):
        trial = current[:i] + current[i + 1:]
        if fails(trial):
            current = trial
            removed = True
            print("removed one element, still fails:", current)
            break
    if not removed:
        break
print("minimal failing input:", current)
print("buggy:", dedupe(current), "expected:", reference(current))

