    trial = current.rsplit(";", 1)[0]
    try:
        parse_packet(trial)
        break
    except ValueError as e:
        if len(trial.split(";")) > 4:
            current = trial
            print(f"down to {len(current.split(';'))} fields, still rejected: {e}")
