def dedupe_old(xs):
    # removes only consecutive duplicates - that limitation was the bug report
    out = []
    for x in xs:
        if not out or out[-1] != x:
            out.append(x)
    return out

def dedupe_new(xs):
    seen = set()
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

